constexpr std::size_t kScoringBins = 256;
constexpr std::size_t kLocalChoices = 3;

double canonical(double phase, double period) {
    phase = std::fmod(phase, period);
    return phase < 0 ? phase + period : phase;
}

double residual(double time, double phase, double period) {
    return std::remainder(time - phase, period);
}

struct ScoredPhase {
    double phase = 0;
    CompletionSupport support;
};

CompletionSupport support_at(
        const std::vector<Transient>& events, double bpm, double phase, double tolerance) {
    const double period = 60 / bpm;
    tolerance = std::min(tolerance, period * 0.12);
    double sum = 0;
    double squares = 0;
    double cluster_weight = 0;
    double cluster_start = events.empty() ? 0 : events.front().time_seconds;
    double matched = 0;
    std::size_t beats = 0;
    std::optional<double> previous_beat;
    for (const auto& event : events) {
        sum += event.weight;
        if (event.time_seconds - cluster_start >= tolerance) {
            squares += cluster_weight * cluster_weight;
            cluster_weight = 0;
            cluster_start = event.time_seconds;
        }
        cluster_weight += event.weight;
        const double error = std::abs(residual(event.time_seconds, phase, period));
        const double kernel = std::max(0.0, 1 - error / tolerance);
        matched += event.weight * kernel;
        if (kernel > 0 && event.weight > 0) {
            const double beat = std::round((event.time_seconds - phase) / period);
            if (!previous_beat || beat != *previous_beat)
                ++beats;
            previous_beat = beat;
        }
    }
    squares += cluster_weight * cluster_weight;
    CompletionSupport result;
    result.expected_background_fraction = tolerance / period;
    if (!(sum > 0))
        return result;
    result.weighted_fraction = matched / sum;
    result.effective_events = sum * sum / squares;
    result.normalized_support = std::max(0.0,
            (result.weighted_fraction - result.expected_background_fraction) /
                    (1 - result.expected_background_fraction));
    const double background = result.expected_background_fraction;
    result.significance = (result.weighted_fraction - background) *
            std::sqrt(result.effective_events / (background * (1 - background)));
    result.supported_beats = beats;
    const double grid_positions = events.empty()
            ? 0
            : std::max(1.0,
                      std::round(
                              (events.back().time_seconds - events.front().time_seconds) / period) +
                              1);
    result.grid_occupancy = grid_positions > 0 ? std::min(1.0, beats / grid_positions) : 0;
    return result;
}

ScoredPhase score_phase(const std::vector<Transient>& events, double bpm, double tolerance) {
    const double period = 60 / bpm;
    tolerance = std::min(tolerance, period * 0.12);
    const auto histogram = phase_histogram(events, period, 0, kScoringBins);
    double phase = period * (static_cast<double>(histogram.peak_bin) + 0.5) / kScoringBins;
    const double histogram_phase = phase;
    std::vector<std::pair<double, double>> folded;
    folded.reserve(events.size());
    for (const auto& event : events) {
        folded.emplace_back(canonical(event.time_seconds, period), event.weight);
    }
    std::sort(folded.begin(), folded.end());
    // Autonomously generated by an AI agent: the circular triangular objective is piecewise linear.
    // Its maximum occurs at an event phase; prefix moments evaluate every such phase in linear time
    // after sorting.
    std::vector<double> positions;
    std::vector<double> weights(1, 0);
    std::vector<double> moments(1, 0);
    positions.reserve(3 * folded.size());
    weights.reserve(3 * folded.size() + 1);
    moments.reserve(3 * folded.size() + 1);
    for (int copy = 0; copy < 3; ++copy) {
        for (const auto& event : folded) {
            const double position = event.first + copy * period;
            positions.push_back(position);
            weights.push_back(weights.back() + event.second);
            moments.push_back(moments.back() + position * event.second);
        }
    }
    double best = -1;
    std::size_t left = 0;
    std::size_t middle = 0;
    std::size_t right = 0;
    for (const auto& event : folded) {
        const double centre = event.first + period;
        while (left < positions.size() && positions[left] < centre - tolerance)
            ++left;
        while (middle < positions.size() && positions[middle] <= centre)
            ++middle;
        while (right < positions.size() && positions[right] < centre + tolerance)
            ++right;
        const double left_weight = weights[middle] - weights[left];
        const double right_weight = weights[right] - weights[middle];
        const double distance = centre * left_weight - (moments[middle] - moments[left]) +
                (moments[right] - moments[middle]) - centre * right_weight;
        const double score = left_weight + right_weight - distance / tolerance;
        if (score > best + 1e-12 * weights.back() ||
                (std::abs(score - best) <= 1e-12 * weights.back() &&
                        std::abs(residual(event.first, histogram_phase, period)) <
                                std::abs(residual(phase, histogram_phase, period)))) {
            best = score;
            phase = event.first;
        }
    }
    // End of autonomously generated AI-agent exact physical mode optimization.
    return {phase, support_at(events, bpm, phase, tolerance)};
}

double local_quality(const CompletionSupport& support) {
    return support.normalized_support * std::sqrt(support.grid_occupancy) *
            std::min(1.0, support.effective_events / 8.0) *
            std::min(1.0, support.supported_beats / 8.0) *
            std::min(1.0, std::max(0.0, support.significance) / 5.0);
}

void add_proposal(std::vector<double>* proposals, double bpm, const CompletionConfig& config) {
    if (bpm < config.minimum_bpm || bpm > config.maximum_bpm || !std::isfinite(bpm))
        return;
    if (std::none_of(proposals->begin(), proposals->end(), [bpm](double previous) {
            return std::abs(previous - bpm) < 0.15;
        }))
        proposals->push_back(bpm);
}

void add_octaves(std::vector<double>* proposals, double bpm, const CompletionConfig& config) {
    for (int octave = -3; octave <= 3; ++octave) {
        add_proposal(proposals, std::ldexp(bpm, octave), config);
    }
}

void validate_config(
        const CompletionConfig& config, double duration, const std::vector<Transient>& events) {
    const auto positive = [](double value) { return std::isfinite(value) && value > 0; };
    if ((config.acceptance_mode != AcceptanceMode::StrictConstant &&
                config.acceptance_mode != AcceptanceMode::BestFitConstant) ||
            !positive(duration) || (!events.empty() && events.back().time_seconds > duration) ||
            !positive(config.minimum_bpm) || config.minimum_bpm < 20 ||
            !positive(config.maximum_bpm) || config.maximum_bpm > 1000 ||
            config.maximum_bpm < config.minimum_bpm || !positive(config.window_seconds) ||
            !positive(config.hop_seconds) || config.hop_seconds > config.window_seconds ||
            config.minimum_events < 3 || !positive(config.phase_tolerance_seconds) ||
            config.phase_tolerance_seconds < 0.000001 || config.phase_tolerance_seconds > 0.1 ||
            !positive(config.minimum_normalized_support) || config.minimum_normalized_support > 1 ||
            !positive(config.minimum_support_significance) ||
            !positive(config.minimum_supported_section_fraction) ||
            config.minimum_supported_section_fraction > 1 ||
            !positive(config.minimum_phase_retention) || config.minimum_phase_retention > 1 ||
            config.maximum_refinements < 1 || config.maximum_refinements > 16 ||
            config.search_plan.empty() || config.search_plan.size() > 16 ||
            duration / config.hop_seconds > 100000) {
        throw std::invalid_argument("invalid completion configuration or duration");
    }
    std::size_t previous_bins = 0;
    for (const auto& stage : config.search_plan) {
        if (!positive(stage.half_width_bpm) || !positive(stage.step_bpm) ||
                stage.half_width_bpm >= config.minimum_bpm || stage.bins < 16 ||
                stage.bins > 65536 || (previous_bins && stage.bins != 2 * previous_bins) ||
                2 * stage.half_width_bpm / stage.step_bpm > 10000) {
            throw std::invalid_argument("invalid completion search plan");
        }
        previous_bins = stage.bins;
    }
}

struct Seed {
    double bpm;
    double vote_weight;
};

std::vector<Seed> aggregate(const std::vector<CompletionLocalEvidence>& evidence) {
    std::vector<CompletionLocalEvidence> sorted = evidence;
    std::stable_sort(sorted.begin(), sorted.end(), [](const auto& a, const auto& b) {
        return a.vote_weight > b.vote_weight;
    });
    std::vector<bool> used(sorted.size());
    std::vector<Seed> seeds;
    for (std::size_t i = 0; i < sorted.size(); ++i) {
        if (used[i])
            continue;
        double weighted_bpm = 0;
        double weight = 0;
        for (std::size_t j = i; j < sorted.size(); ++j) {
            if (!used[j] && std::abs(sorted[j].bpm - sorted[i].bpm) <= sorted[i].bpm * 0.015) {
                used[j] = true;
                weighted_bpm += sorted[j].bpm * sorted[j].vote_weight;
                weight += sorted[j].vote_weight;
            }
        }
        if (weight > 0)
            seeds.push_back({weighted_bpm / weight, weight});
    }
    std::stable_sort(seeds.begin(), seeds.end(), [](const auto& a, const auto& b) {
        return a.vote_weight > b.vote_weight;
    });
    return seeds;
}

double supported_extent(const std::vector<Transient>& events,
        double bpm,
        double phase,
        double tolerance,
        double start,
        double end) {
    const double period = 60 / bpm;
    tolerance = std::min(tolerance, period * 0.12);
    std::optional<double> first;
    double last = 0;
    for (const auto& event : events) {
        if (event.weight > 0 && std::abs(residual(event.time_seconds, phase, period)) < tolerance) {
            if (!first)
                first = event.time_seconds;
            last = event.time_seconds;
        }
    }
    if (!first)
        return 0;
    return std::max(
            0.0, std::min(end, last + period * 0.5) - std::max(start, *first - period * 0.5));
}

CompletionCandidate evaluate_candidate(const std::vector<Transient>& events,
        const std::vector<std::vector<Transient>>& sections,
        const std::vector<CompletionLocalEvidence>& local_evidence,
        double duration,
        double bpm,
        double seed,
        double local_votes,
        const CompletionConfig& config) {
    CompletionCandidate result;
    result.seed_bpm = seed;
    result.bpm = bpm;
    result.local_vote_weight = local_votes;
    const auto phase = score_phase(events, bpm, config.phase_tolerance_seconds);
    result.raw_phase_seconds = phase.phase;
    const auto corrected =
            correct_phase(events, bpm, phase.phase, PhaseWrapPolicy::CanonicalBeatPhase);
    result.recovered_corrected_phase_seconds = canonical(corrected.phase_seconds, 60 / bpm);
    const auto corrected_support = support_at(
            events, bpm, result.recovered_corrected_phase_seconds, config.phase_tolerance_seconds);
    result.phase_correction_retained =
            corrected_support.weighted_fraction >= 0.99 * phase.support.weighted_fraction;
    result.beat_phase_seconds = result.phase_correction_retained
            ? result.recovered_corrected_phase_seconds
            : result.raw_phase_seconds;
    result.support = result.phase_correction_retained ? corrected_support : phase.support;
    double aligned = 0;
    double free_phase = 0;
    double supported_duration = 0;
    std::size_t conflict_run = 0;
    result.evaluated_sections = sections.size();
    for (std::size_t section_index = 0; section_index < sections.size(); ++section_index) {
        const auto& section = sections[section_index];
        if (section.size() < 3) {
            conflict_run = 0;
            continue;
        }
        const auto local = score_phase(section, bpm, config.phase_tolerance_seconds);
        if (local.support.effective_events < 3) {
            conflict_run = 0;
            continue;
        }
        const auto fixed =
                support_at(section, bpm, result.beat_phase_seconds, config.phase_tolerance_seconds);
        double best_local_support = local.support.normalized_support;
        double strongest_quality = 0;
        const CompletionLocalEvidence* strongest = nullptr;
        const double section_start = section_index * config.window_seconds;
        const double section_end = std::min(duration, section_start + config.window_seconds);
        for (const auto& evidence : local_evidence) {
            const double overlap = std::min(section_end, evidence.end_seconds) -
                    std::max(section_start, evidence.start_seconds);
            if (overlap >= 0.5 * (evidence.end_seconds - evidence.start_seconds) &&
                    evidence.support.significance >= 3 && evidence.support.supported_beats >= 4) {
                best_local_support =
                        std::max(best_local_support, evidence.support.normalized_support);
                if (evidence.vote_weight > strongest_quality) {
                    strongest_quality = evidence.vote_weight;
                    strongest = &evidence;
                }
            }
        }
        const double weight = std::min(16.0, local.support.effective_events);
        aligned += weight * fixed.normalized_support;
        free_phase += weight * best_local_support;
        if (fixed.supported_beats >= 3 &&
                fixed.normalized_support >= config.minimum_normalized_support &&
                fixed.normalized_support >= config.minimum_phase_retention * best_local_support) {
            ++result.supported_sections;
            supported_duration += supported_extent(section,
                    bpm,
                    result.beat_phase_seconds,
                    config.phase_tolerance_seconds,
                    section_start,
                    section_end);
        }
        if (strongest && strongest_quality >= 0.3 && strongest->support.effective_events >= 6 &&
                strongest->support.significance >= 5 &&
                fixed.normalized_support <
                        config.minimum_phase_retention * strongest->support.normalized_support) {
            ++result.conflicting_sections;
            ++conflict_run;
            result.longest_conflict_run = std::max(result.longest_conflict_run, conflict_run);
        } else {
            conflict_run = 0;
        }
    }
    result.supported_section_fraction = supported_duration / duration;
    result.phase_retention = free_phase > 0 ? aligned / free_phase : 0;
    result.score = result.support.normalized_support * std::sqrt(result.support.grid_occupancy) *
            std::sqrt(std::max(0.0, result.supported_section_fraction * result.phase_retention));
    if (bpm < config.minimum_bpm || bpm > config.maximum_bpm) {
        result.rejection_reasons.push_back("refinement outside configured BPM limits");
    }
    if (result.support.normalized_support < config.minimum_normalized_support) {
        result.rejection_reasons.push_back(
                "weighted phase support is too close to uniform background");
    }
    if (result.support.significance < config.minimum_support_significance) {
        result.rejection_reasons.push_back(
                "phase support has insufficient effective-event significance");
    }
    if (result.support.supported_beats < 8) {
        result.rejection_reasons.push_back("fewer than eight distinct supported beats");
    }
    if (result.evaluated_sections < std::min<std::size_t>(3, sections.size()) ||
            result.supported_section_fraction < config.minimum_supported_section_fraction ||
            result.phase_retention < config.minimum_phase_retention) {
        result.rejection_reasons.push_back(
                "constant phase is not sustained across time sections; variable tempo or diffuse "
                "evidence");
    }
    if (result.longest_conflict_run >= 2) {
        result.rejection_reasons.push_back(
                "sustained local rhythmic grids contradict the constant grid; tempo or phase "
                "changes are unsupported");
    }
    result.constant_supported = result.rejection_reasons.empty();
    result.accepted = result.constant_supported;
    return result;
}

bool preferred_candidate(
        const CompletionCandidate& candidate, const CompletionCandidate& previous) {
    const auto rank = [](const CompletionCandidate& value) {
        return value.constant_supported ? 2 : (value.accepted ? 1 : 0);
    };
    if (rank(candidate) != rank(previous))
        return rank(candidate) > rank(previous);
    if (candidate.best_fit_estimate && candidate.local_vote_weight != previous.local_vote_weight) {
        return candidate.local_vote_weight > previous.local_vote_weight;
    }
    return candidate.score > previous.score;
}

